This is the exercism dot-dsl exercise. I need to implement Graph. Let me recall the canonical solution:

```python
NODE, EDGE, ATTR = range(3)


class Node:
    def __init__(self, name, attrs):
        self.name = name
        self.attrs = attrs

    def __eq__(self, other):
        return self.name == other.name and self.attrs == other.attrs


class Edge:
    def __init__(self, src, dst, attrs):
        self.src = src
        self.dst = dst
        self.attrs = attrs

    def __eq__(self, other):
        return (self.src == other.src and
                self.dst == other.dst and
                self.attrs == other.attrs)


class Graph:
    def __init__(self, data=None):
        self._data = data or []
        self.nodes = []
        self.edges = []
        self.attrs = {}

    def __repr__(self):
        return f"Graph(nodes={self.nodes}, edges={self.edges}, attrs={self.attrs})"

    @property
    def data(self):
        return self._data

    @data.setter
    def data(self, data):
        self._data = data or []
        self._parse()

    def _parse(self):
        self.nodes = []
        self.edges = []
        self.attrs = {}
        for item in self._data:
            if len(item) < 3:
                raise TypeError("Graph item incomplete")
            kind = item[0]
            if kind == NODE:
                self.nodes.append(Node(*item[1:]))
            elif kind == EDGE:
                self.edges.append(Edge(*item[1:]))
            elif kind == ATTR:
                self.attrs[item[1]] = item[2]
            else:
                raise ValueError("Unknown item")
```

