   - kind == NODE: len must be 3, else ValueError("Node is malformed"); nodes.append(Node(name, attrs))
   - kind == EDGE: len must be 4, else ValueError("Edge is malformed"); edges.append(Edge(src, dst, attrs))
   - else → ValueError("Unknown item")

